import * as THREE from 'three';
import {horizontalGap,isLivingSeatOrTable} from './layout-clearance.js?v=soft-sofa-9-release';
const limits={Living:[-43.1,-37.12,-8.9,-4.18],Dining:[-43.1,-38.78,-4.78,-1.82],Kitchen:[-41,-37.8,-2.8,-.05],'Guest bedroom':[-47.28,-43.35,-4.74,-1.63],'Loft bedroom':[-43.12,-37.04,-7.12,-2.8],'Loft study':[-43.10,-41.2,-6.3,-4.6],Balcony:[-43.1,-37.1,-8.9,-7.25],Terrace:[-47.3,-36.95,-11.03,-9.05],Entry:[-44.5,-38,-.4,.7]};
const protectedZones=[[-43.22,-41.0,-2.22,.1],[-38.95,-37.8,-3.98,-2.77],[-46.1,-45.05,-7.3,-6.13]];
export function createFurnitureEditor({scene,renderer,getCamera,controls,interior,onEnable,onChange,onSelect,filterHit}){
 const controller=new AbortController(),STORAGE='veil-of-light-soft-sofa-9-'+interior.scheme;document.querySelector('#edit-furniture').checked=false;document.querySelector('#furniture-controls').hidden=true;
 const groups=interior.movable,$=s=>document.querySelector(s),select=$('#furniture-select'),ray=new THREE.Raycaster(),mouse=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),0);let enabled=false,selected=null,drag=null,undo=[],helper=null;
 select.replaceChildren();const byId=new Map(groups.map(g=>[g.userData.itemId,g]));for(const g of groups){const option=document.createElement('option');option.value=g.userData.itemId;option.textContent=`${g.userData.room} · ${g.userData.name||g.name}`;select.append(option);}
 const state=()=>groups.map(g=>({id:g.userData.itemId,x:g.position.x,z:g.position.z,rotation:g.rotation.y}));
 const changed=()=>{scene.updateMatrixWorld(true);if(helper)helper.update();onChange();};
 function restore(rows){for(const row of rows){const g=byId.get(row.id);if(g&&[row.x,row.z,row.rotation].every(Number.isFinite)){g.position.x=row.x;g.position.z=row.z;g.rotation.y=row.rotation;}}changed();}
 const original=state();
 function status(message){$('#edit-status').textContent=message;}
 function choose(g){selected=g;select.value=g?.userData.itemId||'';if(helper){scene.remove(helper);helper.geometry.dispose();helper.material.dispose();helper=null;}if(g){onSelect?.(g);helper=new THREE.BoxHelper(g,'#d0e19b');helper.material.depthTest=false;helper.material.transparent=true;helper.material.opacity=.9;helper.renderOrder=20;scene.add(helper);status(`${g.userData.room} · ${g.userData.name||g.name}`);}else status('Choose a piece, then drag it or use the controls.');document.querySelectorAll('[data-furniture-action]').forEach(b=>b.disabled=!g);}
 function valid(g){g.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(g),l=limits[g.userData.room];if(l&&(b.min.x<l[0]||b.max.x>l[1]||b.min.z<l[2]||b.max.z>l[3]))return false;if(b.min.y<2.7)for(const[x0,x1,z0,z1]of protectedZones)if(b.min.x<x1&&b.max.x>x0&&b.min.z<z1&&b.max.z>z0)return false;if(isLivingSeatOrTable(g.userData.itemId)){const a={min:b.min.toArray(),max:b.max.toArray()};for(const other of groups){if(other===g||!isLivingSeatOrTable(other.userData.itemId))continue;const ob=new THREE.Box3().setFromObject(other);if(horizontalGap(a,{min:ob.min.toArray(),max:ob.max.toArray()})<.12)return false;}}return true;}
 function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state()));status('Layout saved on this device.');}catch{status('This browser could not save the layout. You can download it instead.');}}
 function pushUndo(){undo.push(state());if(undo.length>40)undo.shift();$('#undo-furniture').disabled=false;}
 function move(dx,dz,rotation=0){if(!selected)return;const before=state();pushUndo();selected.position.x+=dx;selected.position.z+=dz;selected.rotation.y+=rotation;if(!valid(selected)){restore(before);undo.pop();status('Keep furniture apart and clear of walls, doors and stairs.');}else{changed();save();}}
 function setEnabled(value){if(value)onEnable();enabled=value;$('#edit-furniture').checked=value;$('#furniture-controls').hidden=!value;if(value){choose(selected||groups[0]);status('Select a piece and drag it across its floor. Walls and fixed joinery stay in place.');}else choose(null);}
 $('#edit-furniture').onchange=e=>setEnabled(e.target.checked);select.onchange=()=>choose(byId.get(select.value));
 for(const b of document.querySelectorAll('[data-furniture-action]'))b.onclick=()=>{const a=b.dataset.furnitureAction;if(a==='left')move(-.15,0);if(a==='right')move(.15,0);if(a==='up')move(0,-.15);if(a==='down')move(0,.15);if(a==='rotate-left')move(0,0,Math.PI/12);if(a==='rotate-right')move(0,0,-Math.PI/12);if(a==='reset'){pushUndo();const i=selected.userData.initial;selected.position.x=i.x;selected.position.z=i.z;selected.rotation.y=i.rotation;changed();save();}};
 $('#undo-furniture').onclick=()=>{if(!undo.length)return;restore(undo.pop());$('#undo-furniture').disabled=!undo.length;save();};
 $('#reset-layout').onclick=()=>{pushUndo();restore(original);save();status('Original furniture layout restored.');};
 $('#download-layout').onclick=()=>{const blob=new Blob([JSON.stringify({villa:'Veil of Light',version:1,furniture:state()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='veil-of-light-furniture-layout.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 const pointer=e=>{const rect=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(mouse,getCamera());};
 renderer.domElement.addEventListener('pointerdown',e=>{if(!enabled||e.button!==0)return;pointer(e);const hits=ray.intersectObjects(groups,true).filter(hit=>!filterHit||filterHit(hit));if(!hits.length)return;let g=hits[0].object;while(g&&!g.userData.movable)g=g.parent;if(!g)return;choose(g);plane.constant=-hits[0].point.y;const hit=new THREE.Vector3();if(!ray.ray.intersectPlane(plane,hit))return;pushUndo();drag={start:hit,position:g.position.clone(),before:state()};controls.enabled=false;e.stopImmediatePropagation();renderer.domElement.setPointerCapture(e.pointerId);},{capture:true,signal:controller.signal});
 renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;pointer(e);const hit=new THREE.Vector3();if(!ray.ray.intersectPlane(plane,hit))return;const old=selected.position.clone();selected.position.x=drag.position.x+hit.x-drag.start.x;selected.position.z=drag.position.z+hit.z-drag.start.z;if(!valid(selected)){selected.position.copy(old);status('Leave a gap between furniture and keep access clear.');}else status('Release to save this position.');changed();},{capture:true,signal:controller.signal});
 const finish=()=>{if(!drag)return;drag=null;controls.enabled=true;save();changed();};renderer.domElement.addEventListener('pointerup',finish,{capture:true,signal:controller.signal});renderer.domElement.addEventListener('pointercancel',finish,{capture:true,signal:controller.signal});window.addEventListener('blur',finish,{signal:controller.signal});
 try{const rows=JSON.parse(localStorage.getItem(STORAGE)||'null');if(Array.isArray(rows)){restore(rows);for(const g of groups)if(!valid(g)){const i=g.userData.initial;g.position.x=i.x;g.position.z=i.z;g.rotation.y=i.rotation;}changed();}}catch{}
 return {get enabled(){return enabled;},setEnabled,groups,dispose(){if(drag){drag=null;controls.enabled=true;}choose(null);controller.abort();select.replaceChildren();}};
}
